create extension if not exists pgcrypto;
create sequence if not exists public.sku_sequence start 1;
create table public.shops(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),shop_id uuid not null references shops on delete cascade,name text not null,active boolean not null default true,unique(shop_id,name));
create table public.items(id uuid primary key default gen_random_uuid(),shop_id uuid not null references shops on delete cascade,name text not null,article_no text not null,category_id uuid references categories,default_price numeric(12,2) not null default 0 check(default_price>=0),cost_price numeric(12,2),active boolean not null default true,created_at timestamptz not null default now(),unique(shop_id,article_no));
create table public.variants(id uuid primary key default gen_random_uuid(),shop_id uuid not null references shops on delete cascade,item_id uuid not null references items on delete cascade,color text not null,size text not null,sku_code text not null unique default ('FW'||lpad(nextval('public.sku_sequence')::text,6,'0')),quantity integer not null default 0 check(quantity>=0),active boolean not null default true,created_at timestamptz not null default now(),unique(item_id,color,size));
create table public.stock_entries(id uuid primary key default gen_random_uuid(),shop_id uuid not null references shops on delete cascade,variant_id uuid not null references variants,qty_added integer not null,note text,created_at timestamptz not null default now());
create table public.sales(id uuid primary key default gen_random_uuid(),shop_id uuid not null references shops on delete cascade,variant_id uuid not null references variants,sku_code text not null,listed_price numeric(12,2) not null,sold_price numeric(12,2) not null check(sold_price>=0),sold_at timestamptz not null default now(),status text not null default 'sold' check(status in ('sold','returned')),returned_at timestamptz);
create index variants_shop_sku_idx on variants(shop_id,sku_code); create index items_shop_article_idx on items(shop_id,article_no); create index stock_shop_created_idx on stock_entries(shop_id,created_at desc); create index sales_shop_created_idx on sales(shop_id,sold_at desc); create index variants_shop_item_idx on variants(shop_id,item_id);
alter table shops enable row level security; alter table categories enable row level security; alter table items enable row level security; alter table variants enable row level security; alter table stock_entries enable row level security; alter table sales enable row level security;
create policy "authenticated shops" on shops for all to authenticated using(true) with check(true);
create policy "authenticated categories" on categories for all to authenticated using(true) with check(true);
create policy "authenticated items" on items for all to authenticated using(true) with check(true);
create policy "authenticated variants" on variants for all to authenticated using(true) with check(true);
create policy "authenticated stock_entries" on stock_entries for all to authenticated using(true) with check(true);
create policy "authenticated sales" on sales for all to authenticated using(true) with check(true);
create or replace function public.sell_variant(p_sku_code text,p_sold_price numeric) returns public.sales language plpgsql security invoker set search_path=public as $$ declare v public.variants; i public.items; s public.sales; begin if p_sold_price<0 then raise exception 'Invalid price'; end if; select * into v from variants where sku_code=p_sku_code and active for update; if not found then raise exception 'Unknown barcode'; end if; if v.quantity<1 then raise exception 'Out of stock, cannot sell'; end if; update variants set quantity=quantity-1 where id=v.id; select * into i from items where id=v.item_id; insert into sales(shop_id,variant_id,sku_code,listed_price,sold_price) values(v.shop_id,v.id,v.sku_code,i.default_price,p_sold_price) returning * into s; return s; end $$;
create or replace function public.return_sale(p_sale_id uuid) returns public.sales language plpgsql security invoker set search_path=public as $$ declare s public.sales; begin select * into s from sales where id=p_sale_id and status='sold' for update; if not found then raise exception 'Sale not found or already returned'; end if; update variants set quantity=quantity+1 where id=s.variant_id; update sales set status='returned',returned_at=now() where id=s.id returning * into s; return s; end $$;
create or replace function public.add_stock(p_shop_id uuid,p_item_id uuid,p_color text,p_size text,p_qty integer,p_note text default null) returns public.variants language plpgsql security invoker set search_path=public as $$ declare v public.variants; begin if p_qty<1 then raise exception 'Quantity must be at least one'; end if; insert into variants(shop_id,item_id,color,size,quantity) values(p_shop_id,p_item_id,trim(p_color),trim(p_size),p_qty) on conflict(item_id,color,size) do update set quantity=variants.quantity+excluded.quantity returning * into v; insert into stock_entries(shop_id,variant_id,qty_added,note) values(p_shop_id,v.id,p_qty,p_note); return v; end $$;
create or replace function public.adjust_stock(p_variant_id uuid,p_delta integer,p_note text) returns public.variants language plpgsql security invoker set search_path=public as $$ declare v public.variants; begin if trim(coalesce(p_note,''))='' or p_delta=0 then raise exception 'Reason and non-zero adjustment required'; end if; update variants set quantity=quantity+p_delta where id=p_variant_id and quantity+p_delta>=0 returning * into v; if not found then raise exception 'Adjustment would make stock negative'; end if; insert into stock_entries(shop_id,variant_id,qty_added,note) values(v.shop_id,v.id,p_delta,p_note); return v; end $$;
